SELECT COUNT(*) as count, state FROM t_ds_process_instance WHERE start_time >= TO_TIMESTAMP(#{startTime}, 'YYYY-MM-DD HH:mm:ss') AND start_time <= TO_TIMESTAMP(#{endTime}, 'YYYY-MM-DD HH:mm:ss')
AND state = #{status}
AND project_code IN
